  insert into public.email_signups (email, city_id, source, user_id)
  values (v_email, p_city,
          case when coalesce(p_source, '') ~ '^[a-z0-9_-]{1,40}$' then p_source else 'site' end,
          v_uid)
  on conflict do nothing;
end;
