--
-- Name: moderation_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.moderation_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  j jsonb := to_jsonb(new);
  v text;
begin
  v := public.moderation_violation(
         concat_ws(' ',
           coalesce(j->>'title',''),
           coalesce(j->>'body',''),
           coalesce(j->>'name',''),
           coalesce(j->>'blurb','')
         ));

  if v is not null then
    raise exception 'MODERATION_BLOCKED_%', upper(v)
      using errcode = 'P0001',
            hint = 'Submission rejected by content policy.';
  end if;

  return new;
end $$;


--
-- Name: moderation_normalize(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.moderation_normalize(txt text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  select regexp_replace(
           translate(lower(coalesce(txt,'')),
                     '4310$@!', 'aeiosai'),
           '[^a-z0-9]+', ' ', 'g');
$_$;


--
-- Name: moderation_squash(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.moderation_squash(txt text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select regexp_replace(public.moderation_normalize(txt), '\s+', '', 'g');
$$;


--
-- Name: moderation_violation(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.moderation_violation(txt text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  norm    text := public.moderation_normalize(txt);
  squash  text := public.moderation_squash(txt);
  allowed text;
  hit     record;
begin
  if txt is null or length(trim(txt)) = 0 then
    return null;
  end if;

  -- strip allowlisted phrases first so they can't trip a substring match
  for allowed in select public.moderation_normalize(phrase) from public.moderation_allowlist loop
    norm   := replace(norm, allowed, ' ');
    squash := replace(squash, replace(allowed,' ',''), '');
  end loop;

  -- whole-word match on the normalised text (low false-positive)
  for hit in select term, category from public.moderation_terms loop
    if norm ~ ('\m' || regexp_replace(hit.term, '([.^$*+?()\[\]{}|\\])', '\\\1', 'g') || '\M') then
      return hit.category;
    end if;
  end loop;

  -- substring match on squashed text, strict terms only (catches f u c k)
  for hit in select term, category from public.moderation_terms where strict loop
    if position(replace(hit.term,' ','') in squash) > 0 then
      return hit.category;
    end if;
  end loop;

  return null;
end $_$;


--
-- Name: popular_places(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.popular_places(p_city uuid) RETURNS TABLE(id text, name text, category text, address text, locality text, phone text, website text, lat double precision, lng double precision, status text, review_count integer, picks integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  with pk as (
    select r.place_id, count(*)::int as picks
      from public.top3_picks t join public.restaurants r on r.id = t.restaurant_id
     where r.city_id = p_city and r.place_id is not null
     group by r.place_id
  )
  select c.id, c.name, c.category, c.address, c.locality, c.phone, c.website, c.lat, c.lng, c.status,
         c.review_count, coalesce(pk.picks, 0) as picks
    from public.places_catalog c left join pk on pk.place_id = c.id
   where c.city_id = p_city and coalesce(c.status, '') <> 'closed'
     and (c.review_count is not null or pk.picks is not null)
   order by c.review_count desc nulls last, coalesce(pk.picks, 0) desc, c.confidence desc nulls last
   limit 8;
$$;


--
-- Name: posts_lock_protected(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.posts_lock_protected() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if public.tv_is_privileged() then return new; end if;
  new.ups               := old.ups;
  new.downs             := old.downs;
  new.score             := old.score;
  new.comment_count     := old.comment_count;
  new.city_match        := old.city_match;
  new.submitted_city    := old.submitted_city;
  new.submitted_region  := old.submitted_region;
  new.submitted_country := old.submitted_country;
  new.moderated_at      := old.moderated_at;
  new.moderated_by      := old.moderated_by;
  new.moderation_note   := old.moderation_note;
  new.created_at        := old.created_at;
  new.author_id         := old.author_id;
  -- A new topic goes through review on insert (posts_set_status); adding one
  -- to an already-approved take would skip that, so the topic is fixed too.
  new.topic             := old.topic;
  return new;
end $$;


