    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.status is distinct from old.status and not public.is_admin()
     and current_user not in ('postgres', 'supabase_admin', 'service_role', 'tripvibz_bot') then
    new.status := old.status;
  end if;
  return new;
end $$;


