    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.author_verified is distinct from old.author_verified and not public.is_admin()
     and current_setting('tv.claiming', true) is distinct from 'on' then
    new.author_verified := old.author_verified;
  end if;
  return new;
end $$;


--
-- Name: posts_set_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.posts_set_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if current_user in ('postgres', 'supabase_admin', 'service_role') then return new; end if;
  new.status := case when new.topic is not null then 'pending'::moderation_status
                     else 'approved'::moderation_status end;
  return new;
end $$;


