--

CREATE FUNCTION public.question_votes_check() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not exists (select 1 from public.questions q, jsonb_array_elements(q.options) o
                 where q.id = new.question_id and q.active and o->>'id' = new.option_id) then
    raise exception 'BAD_OPTION' using errcode = 'P0001';
  end if;
  new.verified := public.jwt_is_verified();
  return new;
end $$;


--
-- Name: record_presence(uuid, uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_presence(p_user uuid, p_city uuid, p_near boolean, p_band text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_band is not null and p_band not in ('near', 'region', 'far', 'hosting') then
    raise exception 'bad band' using errcode = '22023';
  end if;
  insert into public.local_checks as lc (user_id, city_id, near, band, checked_at, near_days, first_near, last_near)
  values (p_user, p_city, p_near, p_band, now(),
          case when p_near then 1 else 0 end,
          case when p_near then now() end,
          case when p_near then now() end)
  on conflict (user_id, city_id) do update
     set near       = excluded.near,
         band       = excluded.band,
         checked_at = now(),
         near_days  = lc.near_days
                      + case when excluded.near and (lc.last_near is null or lc.last_near < date_trunc('day', now()))
                             then 1 else 0 end,
         first_near = coalesce(lc.first_near, case when excluded.near then now() end),
         last_near  = case when excluded.near then now() else lc.last_near end
   where not lc.revoked;
end $$;


--
-- Name: redeem_claim(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.redeem_claim(tok text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare a uuid; me uuid := auth.uid(); moved int := 0;
begin
  if me is null or not public.jwt_is_verified() then
    raise exception 'SIGN_IN_FIRST' using errcode = 'P0001';
  end if;
  delete from public.claims where token = tok and expires_at > now() returning anon_user_id into a;
  if a is null or a = me then return 0; end if;
  perform set_config('tv.claiming', 'on', true);
  update public.posts set author_id = me, author_verified = true where author_id = a;
  get diagnostics moved = row_count;
  update public.comments set author_id = me, author_verified = true where author_id = a;
  delete from public.votes v where v.user_id = a and exists (select 1 from public.votes w where w.user_id = me and w.post_id = v.post_id);
  update public.votes set user_id = me where user_id = a;
  delete from public.question_votes v where v.user_id = a and exists (select 1 from public.question_votes w where w.user_id = me and w.question_id = v.question_id);
  update public.question_votes set user_id = me, verified = true where user_id = a;
  insert into public.city_tenure(user_id, city_id, tenure, created_at)
    select me, city_id, tenure, created_at from public.city_tenure where user_id = a
    on conflict (user_id, city_id) do nothing;
  delete from public.city_tenure where user_id = a;
  return moved;
end $$;


--
-- Name: refresh_place_rating(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_place_rating() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare pid uuid;
begin
  pid := coalesce(new.place_id, old.place_id);
  update public.places p set
    review_count = (select count(*) from public.reviews where place_id = pid),
    avg_rating   = coalesce((select round(avg(rating)::numeric,1) from public.reviews where place_id = pid),0)
  where p.id = pid;
  return null;
end; $$;


--
-- Name: restaurants_rate_limit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurants_rate_limit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare n int;
begin
  if new.created_by is not null and not public.is_admin() then
    select count(*) into n from public.restaurants
     where created_by = new.created_by and created_at > now() - interval '24 hours';
    if n >= 10 then raise exception 'RATE_LIMITED' using errcode = 'P0001'; end if;
  end if;
  new.name := btrim(regexp_replace(new.name, '\s+', ' ', 'g'));
  return new;
end $$;


--
-- Name: search_places(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_places(p_city uuid, p_q text) RETURNS TABLE(id text, name text, category text, address text, locality text, phone text, website text, lat double precision, lng double precision, status text, review_count integer, picks integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  with q as (
    select btrim(regexp_replace(regexp_replace(lower(coalesce(p_q, '')), '^\s*the\s+', ''), '[^a-z0-9]+', ' ', 'g')) as key
  ),
  pk as (
    select r.place_id, count(*)::int as picks
      from public.top3_picks t join public.restaurants r on r.id = t.restaurant_id
     where r.city_id = p_city and r.place_id is not null
     group by r.place_id
  )
  select c.id, c.name, c.category, c.address, c.locality, c.phone, c.website, c.lat, c.lng, c.status,
         c.review_count, coalesce(pk.picks, 0) as picks
    from public.places_catalog c
    cross join q
    left join pk on pk.place_id = c.id
   where c.city_id = p_city and length(q.key) >= 2
     and (c.name_key like q.key || '%' or c.name_key like '%' || q.key || '%' or similarity(c.name_key, q.key) > 0.3)
   order by (c.status = 'closed') asc,
            (c.name_key like q.key || '%') desc,
            (c.name_key like '%' || q.key || '%') desc,
            c.review_count desc nulls last,
            coalesce(pk.picks, 0) desc,
            similarity(c.name_key, q.key) desc,
            c.confidence desc nulls last
   limit 8;
$$;


--
-- Name: stamp_moderation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stamp_moderation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status is distinct from old.status then
    new.moderated_at := now();
    new.moderated_by := auth.uid();
  end if;
  return new;
end $$;


--
-- Name: top3_picks_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.top3_picks_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v text;
begin
  -- The restaurant must be in the same city as the list.
  if not exists (select 1 from public.restaurants r where r.id = new.restaurant_id and r.city_id = new.city_id) then
    raise exception 'WRONG_CITY' using errcode = 'P0001';
  end if;
  if new.why is not null then
    new.why := nullif(btrim(regexp_replace(new.why, '\s+', ' ', 'g')), '');
    v := public.moderation_violation(new.why);
    if v is not null then
      raise exception 'MODERATION_BLOCKED_%', upper(v) using errcode = 'P0001', hint = 'Submission rejected by content policy.';
    end if;
  end if;
  new.updated_at := now();
  return new;
end $$;


--
-- Name: tv_is_privileged(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tv_is_privileged() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select public.is_admin()
      or current_user in ('postgres', 'supabase_admin', 'service_role', 'tripvibz_bot')
      or current_setting('tv.claiming', true) = 'on';
$$;


--
-- Name: tv_local_verified(integer, timestamp with time zone, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tv_local_verified(p_days integer, p_first timestamp with time zone, p_last timestamp with time zone, p_revoked boolean) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select coalesce(p_days, 0) >= 3
     and p_first is not null and p_last is not null
     and p_last - p_first >= interval '21 days'
     and not coalesce(p_revoked, false);
$$;


--
-- Name: votes_lock_target(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.votes_lock_target() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if public.tv_is_privileged() then return new; end if;
  new.post_id    := old.post_id;
  new.user_id    := old.user_id;
  new.created_at := old.created_at;
  return new;
end $$;


