--
-- Name: cities_with_counts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.cities_with_counts WITH (security_invoker='true') AS
 SELECT c.id,
    c.name,
    c.state,
    c.slug,
    c.lat,
    c.lng,
    c.blurb,
    c.sort,
    COALESCE(pc.place_count, (0)::bigint) AS place_count,
    COALESCE(tc.take_count, (0)::bigint) AS take_count,
    c.photo
   FROM ((public.cities c
     LEFT JOIN ( SELECT p.city,
            count(*) AS place_count
           FROM public.places p
          WHERE (p.city IS NOT NULL)
          GROUP BY p.city) pc ON ((pc.city = c.name)))
     LEFT JOIN ( SELECT po.city_id,
            count(*) AS take_count
           FROM public.posts po
          WHERE (po.status = 'approved'::public.moderation_status)
          GROUP BY po.city_id) tc ON ((tc.city_id = c.id)));


