--
-- Name: city_founders; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.city_founders WITH (security_invoker='true') AS
 SELECT city_id,
    author_id,
    first_post,
    rank
   FROM ( SELECT p.city_id,
            p.author_id,
            min(p.created_at) AS first_post,
            row_number() OVER (PARTITION BY p.city_id ORDER BY (min(p.created_at))) AS rank
           FROM public.posts p
          WHERE (p.author_verified AND (p.status = 'approved'::public.moderation_status) AND (p.author_id IS NOT NULL) AND (EXISTS ( SELECT 1
                   FROM public.local_checks lc
                  WHERE ((lc.user_id = p.author_id) AND (lc.city_id = p.city_id) AND lc.verified))))
          GROUP BY p.city_id, p.author_id) x
  WHERE (rank <= 10);


