--
-- Name: city_top_restaurants; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.city_top_restaurants WITH (security_invoker='true') AS
 WITH p AS (
         SELECT pk.city_id,
            COALESCE(r_1.merged_into, r_1.id) AS restaurant_id,
            pk.user_id,
            pk.rank,
            pk.why,
            COALESCE((lc.verified AND (NOT lc.revoked)), false) AS verified
           FROM ((public.top3_picks pk
             JOIN public.restaurants r_1 ON ((r_1.id = pk.restaurant_id)))
             LEFT JOIN public.local_checks lc ON (((lc.user_id = pk.user_id) AND (lc.city_id = pk.city_id))))
          WHERE (NOT r_1.hidden)
        )
 SELECT p.city_id,
    p.restaurant_id,
    r.name,
    r.neighborhood,
    r.address,
    r.phone,
    r.website,
    r.lat,
    r.lng,
    r.source,
    (count(*))::integer AS picks,
    (count(*) FILTER (WHERE p.verified))::integer AS verified_picks,
    (sum((4 - p.rank)))::integer AS points,
    (sum(
        CASE
            WHEN p.verified THEN (4 - p.rank)
            ELSE 0
        END))::integer AS verified_points,
    (count(*) FILTER (WHERE (p.rank = 1)))::integer AS firsts
   FROM (p
     JOIN public.restaurants r ON ((r.id = p.restaurant_id)))
  WHERE (NOT r.hidden)
  GROUP BY p.city_id, p.restaurant_id, r.name, r.neighborhood, r.address, r.phone, r.website, r.lat, r.lng, r.source;


