 SELECT p.id,
    p.author_id,
    p.title,
    p.body,
    p.type,
    p.place_id,
    p.ups,
    p.downs,
    p.score,
    p.comment_count,
    p.created_at,
    pr.username AS author_username,
    (log((GREATEST(abs((p.ups - p.downs)), 1))::double precision) + ((sign(((p.ups - p.downs))::double precision) * ((EXTRACT(epoch FROM p.created_at) - (1134028003)::numeric))::double precision) / (45000.0)::double precision)) AS hot_score,
        CASE
            WHEN ((p.downs = 0) OR (p.ups = 0)) THEN (0)::numeric
            ELSE (((p.ups + p.downs))::numeric ^ ((LEAST(p.ups, p.downs))::numeric / (GREATEST(p.ups, p.downs))::numeric))
        END AS controversy_score
   FROM (public.posts p
     LEFT JOIN public.profiles pr ON ((pr.id = p.author_id)));


--
-- Name: reviews; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.reviews (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    place_id uuid NOT NULL,
    author_id uuid,
    rating smallint NOT NULL,
    body text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT reviews_rating_check CHECK (((rating >= 1) AND (rating <= 5)))
);


--
-- Name: take_reviews; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.take_reviews (
    post_id uuid NOT NULL,
    search_phrase text,
    bing_monthly integer,
    hashtag text,
    ig_posts bigint,
    rating text,
    issue_number integer,
    checked_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: votes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.votes (
    user_id uuid NOT NULL,
    post_id uuid NOT NULL,
    value smallint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT votes_value_check CHECK ((value = ANY (ARRAY['-1'::integer, 1])))
);


